local WoodPanelingMaker = {}
local PRODUCTS = {
    simple_pine_paneling = { name = "Preprost borov oblog", woodCost = 3, time = 4, cost = 50, beauty = 22, happiness = 1, description = "Preprost borov oblog za stene." },
    oak_wainscot_paneling = { name = "Hrastova obloga", woodCost = 4, time = 6, cost = 140, beauty = 38, happiness = 2, prestige = 2, description = "Hrastova obloga za trgovce." },
    carved_walnut_paneling = { name = "Izrezljan orehov oblog", woodCost = 4, leatherCost = 1, time = 9, cost = 360, beauty = 52, happiness = 2, prestige = 6, description = "Izrezljan orehov oblog za plemiče." },
    silver_trimmed_paneling = { name = "Srebrnoobrobljeni oblog", woodCost = 4, silverCost = 1, leatherCost = 1, time = 13, cost = 880, beauty = 65, happiness = 3, prestige = 14, description = "Srebrnoobrobljeni oblog za visoke plemiče." },
    gold_inlaid_paneling = { name = "Zlatovloženi oblog", woodCost = 5, goldCost = 1, silverCost = 1, leatherCost = 1, jewelCost = 1, time = 17, cost = 1900, beauty = 78, happiness = 5, prestige = 27, description = "Zlatovloženi oblog z draguljem za visoko plemstvo." },
    royal_grand_paneling = { name = "Kraljevski veliki oblog", woodCost = 7, goldCost = 2, silverCost = 2, leatherCost = 1, jewelCost = 2, pearlCost = 2, time = 24, cost = 4200, beauty = 92, happiness = 12, prestige = 58, description = "Veliki kraljevski oblog z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    paneling_workshop = { name = "Obložna delavnica", cost = { gold = 240, wood = 160, stone = 100 }, upkeep = 5, qualityBonus = 5 },
    woodwork_loft = { name = "Lesna podstrešje", cost = { gold = 880, wood = 320, stone = 240, silver = 6 }, upkeep = 20, qualityBonus = 18 },
    master_woodworker_atelier = { name = "Mojstrski lesarski atelje", cost = { gold = 2500, wood = 380, stone = 480, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_paneling_palace = { name = "Kraljevska obložna palača", cost = { gold = 10500, wood = 600, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
WoodPanelingMaker.woodStock = 20; WoodPanelingMaker.leatherStock = 8; WoodPanelingMaker.silverStock = 6; WoodPanelingMaker.goldStock = 6; WoodPanelingMaker.jewelStock = 4; WoodPanelingMaker.pearlStock = 4
WoodPanelingMaker.productStock = {}; WoodPanelingMaker.buildings = {}; WoodPanelingMaker.maker = nil; WoodPanelingMaker.activeMaking = {}; WoodPanelingMaker.totalProducts = 0; WoodPanelingMaker.dayTimer = 0
function WoodPanelingMaker.init() WoodPanelingMaker.woodStock=20; WoodPanelingMaker.leatherStock=8; WoodPanelingMaker.silverStock=6; WoodPanelingMaker.goldStock=6; WoodPanelingMaker.jewelStock=4; WoodPanelingMaker.pearlStock=4; WoodPanelingMaker.productStock={}; WoodPanelingMaker.buildings={}; WoodPanelingMaker.maker=nil; WoodPanelingMaker.activeMaking={}; WoodPanelingMaker.totalProducts=0; WoodPanelingMaker.dayTimer=0; print("[WoodPanelingMaker] Royal Wood Paneling Maker System initialized (6 products, 4 buildings)") end
function WoodPanelingMaker.hireMaker(n,s) s=s or math.random(55,90); local c=520+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; WoodPanelingMaker.maker={name=n or ("Oblogar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Oblogar najet: %s (spretnost: %d)",WoodPanelingMaker.maker.name,s),"success") end; return true end
function WoodPanelingMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function WoodPanelingMaker.build(id) local ok,e=WoodPanelingMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(WoodPanelingMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function WoodPanelingMaker.getQualityBonus() local b=0; for _,bd in ipairs(WoodPanelingMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function WoodPanelingMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and WoodPanelingMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and WoodPanelingMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and WoodPanelingMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and WoodPanelingMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and WoodPanelingMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and WoodPanelingMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #WoodPanelingMaker.buildings==0 then return false,"Potrebna obložna delavnica" end; if not WoodPanelingMaker.maker then return false,"Potreben oblogar" end; return true end
function WoodPanelingMaker.make(pt,qty) qty=qty or 1; local ok,e=WoodPanelingMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then WoodPanelingMaker.woodStock=WoodPanelingMaker.woodStock-d.woodCost*qty end; if d.leatherCost then WoodPanelingMaker.leatherStock=WoodPanelingMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then WoodPanelingMaker.silverStock=WoodPanelingMaker.silverStock-d.silverCost*qty end; if d.goldCost then WoodPanelingMaker.goldStock=WoodPanelingMaker.goldStock-d.goldCost*qty end; if d.jewelCost then WoodPanelingMaker.jewelStock=WoodPanelingMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then WoodPanelingMaker.pearlStock=WoodPanelingMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if WoodPanelingMaker.maker then t=math.max(1,t-math.floor(WoodPanelingMaker.maker.skill/13)) end; table.insert(WoodPanelingMaker.activeMaking,{id="paneling_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Polaganje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function WoodPanelingMaker.completeMaking(m) local q=1.0+(WoodPanelingMaker.getQualityBonus()/100); if WoodPanelingMaker.maker then q=q+(WoodPanelingMaker.maker.skill/140) end; q=math.min(2.5,q); WoodPanelingMaker.productStock[m.productType]=(WoodPanelingMaker.productStock[m.productType] or 0)+m.quantity; WoodPanelingMaker.totalProducts=WoodPanelingMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if WoodPanelingMaker.maker then WoodPanelingMaker.maker.itemsMade=WoodPanelingMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then WoodPanelingMaker.maker.skill=math.min(100,WoodPanelingMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Oblog izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"paneling.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function WoodPanelingMaker.update(dt) if not _G.state then return end; WoodPanelingMaker.dayTimer=WoodPanelingMaker.dayTimer+dt; if WoodPanelingMaker.dayTimer>=30 then WoodPanelingMaker.dayTimer=0; for i=#WoodPanelingMaker.activeMaking,1,-1 do local m=WoodPanelingMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then WoodPanelingMaker.completeMaking(m); table.remove(WoodPanelingMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(WoodPanelingMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if WoodPanelingMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function WoodPanelingMaker.getStats() return {woodStock=WoodPanelingMaker.woodStock,leatherStock=WoodPanelingMaker.leatherStock,silverStock=WoodPanelingMaker.silverStock,goldStock=WoodPanelingMaker.goldStock,jewelStock=WoodPanelingMaker.jewelStock,pearlStock=WoodPanelingMaker.pearlStock,productStock=WoodPanelingMaker.productStock,numBuildings=#WoodPanelingMaker.buildings,hasMaker=WoodPanelingMaker.maker~=nil,makerName=WoodPanelingMaker.maker and WoodPanelingMaker.maker.name or "—",makerSkill=WoodPanelingMaker.maker and WoodPanelingMaker.maker.skill or 0,activeMaking=#WoodPanelingMaker.activeMaking,totalProducts=WoodPanelingMaker.totalProducts} end
return WoodPanelingMaker
